function findMaxLength(nums) {
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    let balance = 0;
    for (let j = i; j < nums.length; j++) {
      balance += nums[j] === 1 ? 1 : -1;
      if (balance === 0 && j - i + 1 > best) best = j - i + 1;
    }
  }
  return best;
}

