function findMaxLength(nums) {
  const firstIndex = new Map([[0, -1]]);
  let balance = 0;
  let best = 0;
  for (let i = 0; i < nums.length; i++) {
    balance += nums[i] === 1 ? 1 : -1;
    if (firstIndex.has(balance)) {
      const length = i - firstIndex.get(balance);
      if (length > best) best = length;
    } else {
      firstIndex.set(balance, i);
    }
  }
  return best;
}

code.python:
def find_max_length(nums):
    first_index = {0: -1}
    balance = 0
    best = 0
    for i, value in enumerate(nums):
        balance += 1 if value == 1 else -1
        if balance in first_index:
            length = i - first_index[balance]
            if length > best:
                best = length
        else:
            first_index[balance] = i
    return best

